  /** Tolerance used by the EvoSuite-generated assertions on the returned root. */
  private static final double ASSERT_TOLERANCE = 0.01;

  /**
   * Solving the cube-root function over a bracket whose lower endpoint is the
   * negative root returns a root at (approximately) zero.
   */
  @Test(timeout = 4000)
  public void solveCbrtOverWideBracketFindsRootNearZero() throws Throwable {
      MullerSolver solver = new MullerSolver();
      Cbrt cbrt = new Cbrt();

      double root = solver.solve(1392203, (UnivariateFunction) cbrt, -2825.0795928397, 2.7950664235456177E85);

      assertEquals(0.0, root, ASSERT_TOLERANCE);
  }

  /**
   * Solving the sine function over a bracket that never converges within the
   * allowed evaluation budget exhausts the maximal evaluation count and throws.
   */
  @Test(timeout = 4000)
  public void solveSinExceedingEvaluationBudgetThrows() throws Throwable {
      MullerSolver solver = new MullerSolver();
      Sin sin = new Sin();

      try {
        solver.solve(2331, (UnivariateFunction) sin, 3824.7097985564, 3.8581732071331E174);
        fail("Expecting exception: RuntimeException");
      } catch (RuntimeException e) {
         // illegal state: maximal count (2,331) exceeded: evaluations
         verifyException("org.apache.commons.math4.legacy.analysis.solvers.BaseAbstractUnivariateSolver", e);
      }
  }

  /**
   * Solving the cube-root function over a bracket from a negative lower endpoint
   * up to a positive upper endpoint converges to a root very close to zero.
   */
  @Test(timeout = 4000)
  public void solveCbrtOverNegativeToPositiveBracketFindsRootNearZero() throws Throwable {
      MullerSolver solver = new MullerSolver();
      Cbrt cbrt = new Cbrt();

      double root = solver.solve(2331, (UnivariateFunction) cbrt, -1321.9, (double) 2331);

      assertEquals(3.060102951752152E-7, root, ASSERT_TOLERANCE);
  }

  /**
   * Solving a zero polynomial (every coefficient is zero) with the single
   * start-value overload returns NaN, since no unique root can be located.
   */
  @Test(timeout = 4000)
  public void solveZeroPolynomialReturnsNaN() throws Throwable {
      MullerSolver solver = new MullerSolver(1.0E-15);
      double[] zeroCoefficients = new double[4];
      PolynomialFunction zeroPolynomial = new PolynomialFunction(zeroCoefficients);

      double root = solver.solve(5575, (UnivariateFunction) zeroPolynomial, 0.0016310069148432287);

      assertEquals(Double.NaN, root, ASSERT_TOLERANCE);
  }

  /**
   * Solving the cube-root function over a bracket whose upper endpoint is a
   * tiny positive value returns that upper endpoint as the located root.
   */
  @Test(timeout = 4000)
  public void solveCbrtWithTinyPositiveUpperBoundReturnsUpperBound() throws Throwable {
      MullerSolver solver = new MullerSolver();
      Cbrt cbrt = new Cbrt();

      double root = solver.solve(2331, (UnivariateFunction) cbrt, -1476.2544696353405, 4.800501435803201E-220);

      assertEquals(4.800501435803201E-220, root, ASSERT_TOLERANCE);
  }

  /**
   * Solving the ulp function with the single start-value overload, using a
   * solver configured with explicit relative and function-value accuracies,
   * returns the start value itself as the root.
   */
  @Test(timeout = 4000)
  public void solveUlpWithCustomAccuraciesReturnsStartValue() throws Throwable {
      MullerSolver solver = new MullerSolver(3.1660099222737955E-7, -4620.5448992389);
      Ulp ulp = new Ulp();

      double root = solver.solve(2048, (UnivariateFunction) ulp, 1.5902118682861328);

      assertEquals(1.5902118682861328, root, ASSERT_TOLERANCE);
  }
